// Room: D-pad run, C jump, B slash (UP + B upward), DOWN crouch, DOWN + C drop, START = floor map.
// Map:  START back, A run/stop the Void, B show everything (debug), C new floor.

enum { MODE_ROOM, MODE_MAP };

#define MAP_X 2
#define MAP_Y 3

static Level lv;
static Player player;
static u8 mode = MODE_ROOM;
static u8 depth = 1;
static bool showSecrets = FALSE;
static u16 dying;            // frames since the hero died (0: alive), updateDeath
static u8 backToTitle;       // the run is over: runGame returns to the title
// Frames the display stays off after a room change (Thomas, 2026-11-18: a jumble of sprites before
// the new room showed). The new room's tiles are loaded while the old sprites were still on screen:
// the display goes off for the change and comes back once the new sprites have reached video memory.
static u8 screenOff;

// What the shared stretches of video memory hold (drawSprites); gfx_load leaves 0 everywhere.
static u8 bossArt, captainArt, shopArt;

// ---------------------------------------------------------------- floor map

static const char LETTER[] = { ' ', '.', 'S', 'B', 'U', '$', '?', '!' };


static void drawCell(u8 x, u8 y)
{
    u8 t = lv.floor.type[y][x];
    u8 secret = t == ROOM_SECRET || t == ROOM_SUPER_SECRET;
    if (t == ROOM_NONE || (secret && !showSecrets && !lv.visited[y][x])) return;

    // Like Isaac: visited rooms are known, rooms behind a visible door of a visited room are guessed.
    u8 known = showSecrets || lv.visited[y][x];
    u8 guessed = (x > 0 && lv.visited[y][x - 1] && (level_doors(&lv, x - 1, y) & DOOR_RIGHT))
        || (x < FLOOR_W - 1 && lv.visited[y][x + 1] && (level_doors(&lv, x + 1, y) & DOOR_LEFT))
        || (y > 0 && lv.visited[y - 1][x] && (level_doors(&lv, x, y - 1) & DOOR_DOWN))
        || (y < FLOOR_H - 1 && lv.visited[y + 1][x] && (level_doors(&lv, x, y + 1) & DOOR_UP));
    if (!known && !guessed) return;

    u16 px = MAP_X + x * 4, py = MAP_Y + y * 2;
    u16 pal = PAL0;
    if (t == ROOM_BOSS) pal = PAL1;
    else if (t >= ROOM_UPGRADE) pal = PAL2;
    if (!secret && level_cellInVoid(&lv, x, y)) pal = PAL3;

    char cell[4] = { '[', known ? LETTER[t] : ' ', ']', 0 };
    if (x == lv.cellX && y == lv.cellY) cell[1] = '@';
    VDP_setTextPalette(pal);
    VDP_drawText(cell, px, py);

    // Doors are drawn by the room on their left/top side only.
    u8 doors = level_doors(&lv, x, y), hidden = showSecrets ? lv.floor.hidden[y][x] & ~lv.opened[y][x] : 0;
    if (!known)   // only the doors leading back to visited rooms
    {
        if (!(x < FLOOR_W - 1 && lv.visited[y][x + 1])) doors &= ~DOOR_RIGHT;
        if (!(y < FLOOR_H - 1 && lv.visited[y + 1][x])) doors &= ~DOOR_DOWN;
    }
    VDP_setTextPalette(PAL0);
    if (doors & DOOR_RIGHT) VDP_drawText("-", px + 3, py);
    if (doors & DOOR_DOWN) VDP_drawText("|", px + 1, py + 1);
    VDP_setTextPalette(PAL2);
    if (hidden & DOOR_RIGHT) VDP_drawText("=", px + 3, py);
    if (hidden & DOOR_DOWN) VDP_drawText(":", px + 1, py + 1);
}

// Test tools, at the bottom of the pause screen (A / B / C, updateMap).
static void drawMapStatus(void)
{
    char line[41];
    VDP_setTextPalette(PAL2);
    sprintf(line, "%04X R%-4u A NEANT %s B TOUT C ETAGE ", lv.floor.seed, (u16) (lv.voidRadiusFx >> 8),
            lv.voidRunning ? "ON " : "OFF");
    VDP_drawText(line, 1, 27);
}

// The pause screen (Thomas, 2026-11-18: START shows the map and a reminder of everything the hero
// has; the special moves will be chosen here): the map, then life, coins, keys, special moves and
// the upgrades taken.
static void drawMap(void)
{
    char line[41];
    VDP_clearPlane(BG_A, TRUE);
    VDP_clearPlane(BG_B, TRUE);
    VDP_setTextPalette(PAL0);
    sprintf(line, "PAUSE                        ETAGE %u", depth);
    VDP_drawText(line, 2, 1);
    for (u8 y = 0; y < FLOOR_H; y++)
        for (u8 x = 0; x < FLOOR_W; x++) drawCell(x, y);
    VDP_setTextPalette(PAL0);
    sprintf(line, "COEURS %d%s/%d  PIECES %u  CLES %u", player.hp / 2, player.hp & 1 ? ",5" : "",
            player.maxHp / 2, player.coins, player.keys);
    VDP_drawText(line, 2, 20);
    VDP_drawText("COUPS SPECIAUX  AUCUN", 2, 21);
    VDP_drawText("OBJETS", 2, 22);
    u8 n = 0;
    for (u8 i = 0; i < UPGRADE_COUNT; i++)
        if (player.owned & (1 << i))
        {
            VDP_setTextPalette(i + ITEM_FIRST_UPGRADE >= ITEM_GLASS_HEART ? PAL1 : PAL0);   // the bad ones in red
            VDP_drawText(player_itemName(i + ITEM_FIRST_UPGRADE), 4 + (n & 1) * 18, 23 + n / 2);
            n++;
        }
    if (!n) VDP_drawText("AUCUN", 9, 22);
    drawMapStatus();
}

// The bestiary and the options on the cartridge's battery-backed SRAM (rom_head.c declares it).
static void saveCodex(void)
{
    u8 bytes[CODEX_BYTES];
    codex_pack(bytes);
    SRAM_enable();
    for (u8 i = 0; i < CODEX_BYTES; i++) SRAM_writeByte(i, bytes[i]);
    SRAM_disable();
}

static void loadCodex(void)
{
    u8 bytes[CODEX_BYTES];
    SRAM_enableRO();
    for (u8 i = 0; i < CODEX_BYTES; i++) bytes[i] = SRAM_readByte(i);
    SRAM_disable();
    codex_unpack(bytes);   // nothing saved yet (or damaged): an empty bestiary
}

// The pad: detected, or forced to 3 or 6 buttons (options).
static void applyPadMode(void)
{
    if (codex.padMode == PAD_MODE_AUTO) JOY_reset();
    else JOY_setSupport(PORT_1, codex.padMode == PAD_MODE_3 ? JOY_SUPPORT_3BTN : JOY_SUPPORT_6BTN);
}

static void newFloor(u16 seed)
{
    saveCodex();   // what was met so far is kept, whatever happens next
    // Floors 1-2 the forest, then outside by the graveyard, then the castle (Thomas, 2026-11-19).
    u8 world = depth <= 2 ? WORLD_FOREST : depth <= 6 ? WORLD_GRAVEYARD : WORLD_CASTLE;
    VDP_setEnable(FALSE);   // its tiles load over the old ones: no jumble on screen (updateRoom turns it back on)
    screenOff = 2;
    decor_setWorld(world);
    gfx_setWorld(world);
    level_start(&lv, &player, seed, depth);
    gfx_setEnemyTier(enemies_tier());
}

static void updateMap(u16 pressed)
{
    if (pressed & BUTTON_C)
    {
        depth = depth % 7 + 1;   // every floor: 1-2 forest, 3-6 graveyard, 7 castle
        newFloor(random() ^ vtimer);
        VDP_setEnable(TRUE);   // the pause screen stays on (newFloor turns the display off)
        screenOff = 0;
        drawMap();
    }
    if (pressed & BUTTON_B)
    {
        showSecrets = !showSecrets;
        drawMap();
    }
    if (pressed & BUTTON_A)
    {
        lv.voidRunning = !lv.voidRunning && lv.voidRadiusFx;
        drawMapStatus();
    }
}

// ---------------------------------------------------------------- room

// Camera: the room is streamed into a 64 x 32 tile plane that wraps around. Only the visible
// 41 x 29 tiles must be valid, so each step of one tile redraws one column or one row.
static s16 camX, camY;          // top-left of the screen, room pixels
static s16 drawnTX, drawnTY;    // camera tile the plane currently matches

// The Void circle on screen: for each visible row, the room columns inside the circle form one
// interval [in0, in1). One square root per row gives it, so the edge costs almost nothing and only
// the tiles crossing it are rewritten. Inside: high priority (normal). Outside: low priority, which
// the shadow/highlight mode draws at half brightness: the castle is seen through the Void, darkened.
static s16 rowRoomY[32];          // room row currently held by each plane row
static s16 rowIn0[32], rowIn1[32];

static u16 isqrt32(u32 v)
{
    u16 lo = 0, hi = 0xFFFF;
    while (lo < hi)
    {
        u16 mid = lo + (hi - lo + 1) / 2;
        if ((u32) mid * mid <= v) lo = mid;
        else hi = mid - 1;
    }
    return lo;
}

static void rowInterval(s16 ty, s16 *in0, s16 *in1)
{
    s16 r = lv.voidRadiusFx >> 8;
    s16 wy = lv.cellY * CELL_H_PX + ty * 8 + 4 - lv.voidCY;
    if (wy > r || -wy > r)
    {
        *in0 = *in1 = 0;
        return;
    }
    s16 half = isqrt32((u32) r * r - (u32) ((s32) wy * wy));
    s16 cx = lv.voidCX - lv.cellX * CELL_W_PX;   // circle centre in room pixels
    *in0 = (cx - half - 4 + 7) >> 3;             // first tile whose centre is inside
    *in1 = ((cx + half - 4) >> 3) + 1;
}
static u8 roomTile(s16 tx, s16 ty)
{
    if (tx < 0 || ty < 0 || tx >= lv.room.w || ty >= lv.room.h) return TILE_SOLID;   // walls go on
    return lv.room.tiles[ty][tx];
}

// Room tile or decor for a room cell (decor_planeTile, game_decor.c), or a cracked wall hiding a
// secret room.
static u16 castleTile(s16 tx, s16 ty)
{
    if (lv.crackedCount && roomTile(tx, ty) == TILE_SOLID && level_crackedAt(&lv, tx * 8 + 4, ty * 8 + 4))
        return CASTLE_CRACKED + ((ty & 1) << 1 | (tx & 1));
    return decor_planeTile(&lv.room, tx, ty);
}

// Room tiles stay in front (high priority) unless the Void has swallowed them: the shadow mode then
// darkens them. Empty tiles show the decor (trees, graves, fence), with the same priority.
static u8 shopShown;   // the shop's picture is on the far plane (gfx_loadShopRoom)

static void drawTileState(s16 tx, s16 ty, u8 inVoid)
{
    if (shopShown)   // the picture is the whole room
    {
        VDP_setTileMapXY(ROOM_PLANE, TILE_ATTR_FULL(PAL0, 1, 0, 0, 0), tx & 63, ty & 31);
        return;
    }
    u16 index = castleTile(tx, ty), tile = 0;
    if (index & DECOR_TILE) tile = gfx_decorTile(index & 0xFF);
    else if (index & ~CASTLE_FLIP) tile = GFX_CASTLE + (index & ~CASTLE_FLIP);
    VDP_setTileMapXY(ROOM_PLANE, TILE_ATTR_FULL(PAL0, !inVoid, 0, (index & CASTLE_FLIP) != 0, tile), tx & 63, ty & 31);
}

static void drawColumn(s16 tx)
{
    for (s16 ty = drawnTY; ty <= drawnTY + SCREEN_H_TILES; ty++)
    {
        u8 cy = ty & 31;
        drawTileState(tx, ty, tx < rowIn0[cy] || tx >= rowIn1[cy]);
    }
}

static void drawRow(s16 ty)
{
    u8 cy = ty & 31;
    rowInterval(ty, &rowIn0[cy], &rowIn1[cy]);
    rowRoomY[cy] = ty;
    for (s16 tx = drawnTX; tx <= drawnTX + SCREEN_W_TILES; tx++)
        drawTileState(tx, ty, tx < rowIn0[cy] || tx >= rowIn1[cy]);
}
static void updateCamera(void)
{
    // Dead zone: the camera only moves when the ninja leaves a box around the screen centre.
    s16 px = player.x >> 8, py = player.y >> 8;
    if (px < camX + 144) camX = px - 144;
    if (px > camX + 176) camX = px - 176;
    if (py < camY + 96) camY = py - 96;
    if (py > camY + 160) camY = py - 160;

    s16 maxX = lv.room.w * ROOM_TILE - SCREEN_W_TILES * ROOM_TILE;
    s16 maxY = lv.room.h * ROOM_TILE - SCREEN_H_TILES * ROOM_TILE;
    if (camX > maxX) camX = maxX;
    if (camY > maxY) camY = maxY;
    if (camX < 0) camX = 0;
    if (camY < 0) camY = 0;
}

// Parallax (the line scroll mode, one horizontal offset per screen line): FAR_PLANE is cut into bands
// of rows (far_bands.h, written with the picture by tools/art/make_art.py), from the high clouds to
// the forest, each drifting at its own fraction of the room's speed. It is 256 rows tall: its
// vertical offset follows the camera from the top of the room (0) to the bottom (32), so it never
// wraps. Both tables go to video memory by DMA during the next vertical blank.
static s16 scrollRoom[224], scrollBands[224];
static void scrollFar(void)
{
    s16 maxY = lv.room.h * ROOM_TILE - SCREEN_H_TILES * ROOM_TILE;
    s16 vB = maxY > 0 ? (s16) ((u32) camY * 32 / (u16) maxY) : 32;
    u16 worldX = lv.cellX * CELL_W_PX + camX;
    const u16 *bandEnd, *bandSpeed;
    const s16 *bandDrift;
    u8 bands = gfx_farBands(&bandEnd, &bandSpeed, &bandDrift);
    s16 band[FAR_BANDS];   // world 1 has the most
    for (u8 b = 0; b < bands; b++)
        band[b] = -(s16) (((u32) worldX * bandSpeed[b]) >> 5) - bandDrift[b] * (s16) (vtimer >> 4);
    if (shopShown)   // one still picture
    {
        vB = 0;
        for (u8 i = 0; i < bands; i++) band[i] = 0;
    }
    u8 b = 0;
    for (u16 line = 0; line < 224; line++)
    {
        u16 row = line + vB;
        while (b < bands - 1 && row >= bandEnd[b]) b++;
        scrollRoom[line] = -camX;
        scrollBands[line] = band[b];
    }
    VDP_setHorizontalScrollLine(ROOM_PLANE, 0, scrollRoom, 224, DMA_QUEUE);
    VDP_setHorizontalScrollLine(FAR_PLANE, 0, scrollBands, 224, DMA_QUEUE);
    VDP_setVerticalScroll(FAR_PLANE, vB);
}

static void scrollCamera(void)
{
    s16 tx = camX >> 3, ty = camY >> 3;
    while (drawnTX < tx) { drawnTX++; drawColumn(drawnTX + SCREEN_W_TILES); }
    while (drawnTX > tx) { drawnTX--; drawColumn(drawnTX); }
    while (drawnTY < ty) { drawnTY++; drawRow(drawnTY + SCREEN_H_TILES); }
    while (drawnTY > ty) { drawnTY--; drawRow(drawnTY); }
    // The boss lands: the room shakes under the sprites for a moment.
    s16 shake = lv.enemies.shake ? ((lv.enemies.shake & 2) ? 2 : -2) : 0;
    VDP_setVerticalScroll(ROOM_PLANE, camY + shake);
    scrollFar();
}

// Each frame: new interval per visible row, rewrite only the columns between the old and new edges.
static void rewriteSpan(s16 ty, s16 a, s16 b, s16 in0, s16 in1)
{
    if (a > b) { s16 t = a; a = b; b = t; }
    if (a < drawnTX) a = drawnTX;
    if (b > drawnTX + SCREEN_W_TILES + 1) b = drawnTX + SCREEN_W_TILES + 1;
    for (s16 tx = a; tx < b; tx++) drawTileState(tx, ty, tx < in0 || tx >= in1);
}

static void refreshVoid(void)
{
    for (s16 ty = drawnTY; ty <= drawnTY + SCREEN_H_TILES; ty++)
    {
        u8 cy = ty & 31;
        s16 in0, in1;
        rowInterval(ty, &in0, &in1);
        if (in0 == rowIn0[cy] && in1 == rowIn1[cy]) continue;
        if (in0 >= in1 || rowIn0[cy] >= rowIn1[cy])
            rewriteSpan(ty, rowIn0[cy] < rowIn1[cy] ? rowIn0[cy] : in0, rowIn0[cy] < rowIn1[cy] ? rowIn1[cy] : in1, in0, in1);
        else
        {
            rewriteSpan(ty, rowIn0[cy], in0, in0, in1);
            rewriteSpan(ty, rowIn1[cy], in1, in0, in1);
        }
        rowIn0[cy] = in0;
        rowIn1[cy] = in1;
    }
}
// Middle of the open trapdoor of the room, room pixels (trapX < 0: none). Its plank looks like any
// other, so an arrow floats over it. Templates keep their two bottom rows of blocks for the floor: a
// plank there can only be the cover of the hole. Looked up again each time the room is drawn, so the
// arrow goes when the boss locks the doors.
static s16 trapX, trapY;

static void findTrapdoor(void)
{
    s16 ty = lv.room.h - 4, first = -1, last = -1;
    for (s16 tx = 0; tx < lv.room.w; tx++)
        if (lv.room.tiles[ty][tx] == TILE_PLATFORM)
        {
            if (first < 0) first = tx;
            last = tx;
        }
    trapX = first < 0 ? -1 : (first + last + 1) * 4;
    trapY = ty * 8;
}

// Decor of the room drawn last (cell index; 0xFF: none). Placed again on a room change only: a
// door crossing redraws through drawRoom, not enterRoom, and kept the last room's fences and graves,
// floating in the new one (Thomas); a wall broken open must not move them.
static u8 decorCell = 0xFF;

static void drawRoom(void)
{
    u8 cell = lv.cellY * FLOOR_W + lv.cellX;
    u8 inShop = lv.cellX == lv.shopX && lv.cellY == lv.shopY;
    if (inShop != shopShown)
    {
        shopShown = inShop;
        gfx_loadShopRoom(inShop);
    }
    if (cell != decorCell)
    {
        decorCell = cell;
        decor_place(&lv.room, lv.floor.seed ^ (lv.cellX * 77 + lv.cellY * 1031));
    }
    findTrapdoor();
    updateCamera();
    drawnTX = camX >> 3;
    drawnTY = camY >> 3;
    for (s16 ty = drawnTY; ty <= drawnTY + SCREEN_H_TILES; ty++) drawRow(ty);
    scrollCamera();
}

// Sprites: 0 hero, 1 slash, 2.. enemies, then shots, gem, item, props, pickups, rest of the hero.
// An enemy pose is 1 to 4 sprites. The console shows 80 sprites in all: the enemies share a pool
// instead of owning 4 each (12 enemies never show their widest pose on one screen together).
#define SPRITE_ENEMIES 2
#define ENEMY_SPRITES 30
#define SPRITE_BAR (SPRITE_ENEMIES + ENEMY_SPRITES)   // 3 sprites: name of the enemy last hit, its life
#define SPRITE_SHOTS (SPRITE_BAR + 3)
#define SPRITE_GEM (SPRITE_SHOTS + MAX_SHOTS)
#define SPRITE_ITEM (SPRITE_GEM + 1)
#define SPRITE_TRAP (SPRITE_ITEM + 1)     // arrow over the trapdoor
#define SPRITE_PROPS (SPRITE_TRAP + 1)
#define SPRITE_PICKUPS (SPRITE_PROPS + MAX_PROPS)
#define SPRITE_EXT2 (SPRITE_PICKUPS + MAX_PICKUPS)   // second extension cell of the hero
#define SPRITE_EXT3 (SPRITE_EXT2 + 1)       // third one (big slash crescents)
#define SPRITE_BODY_LOW (SPRITE_EXT3 + 1)   // hero below row 32 (hardware sprites are 4 x 4 tiles max)
#define SPRITE_HIT (SPRITE_BODY_LOW + 1)    // spark of a blow; chained right after the hero, over the enemies
#define SPRITE_HUD (SPRITE_HIT + 1)        // 10 sprites: hearts 3, light 3, coins, minimap 2, keys
#define SPRITE_COUNT (SPRITE_HUD + 10)

// Animation frame from the player's state. Running advances one frame every 7 px travelled,
// so the legs match the ground speed (and the upgrades that change it).
static u8 ninjaFrame(void)
{
    static u16 runDistance;
    static u8 runFrame, landTimer, wasOnGround = 1;
    if (player.onGround && !wasOnGround) landTimer = 5;
    wasOnGround = player.onGround;
    if (landTimer) landTimer--;
    if (player.hp <= 0) return player.onGround ? NINJA_DEAD : NINJA_HURT;   // dead: lying on the ground
    if (player.hurtTimer) return NINJA_HURT;
    // The slash shows only its wind-up and its crescent: no end pose, the recovery (no new slash yet)
    // keeps the normal animation (Thomas, 2026-11-17).
    if (player.attackTimer && player_attackStep(&player) < 3)
    {
        u8 step = player_attackStep(&player);
        if (player.attackDir == ATTACK_UP) return NINJA_UP0 + step;
        if (player.attackDir == ATTACK_DOWN) return NINJA_DOWN0 + step;
        if (player.crouching) return step == 1 || step == 2 ? NINJA_CROUCH_SLASH1 : NINJA_CROUCH_SLASH0;
        if (!player.onGround) return NINJA_AIR0 + step;
        return NINJA_SLASH0 + step;
    }
    if (player.crouching) return NINJA_CROUCH;
    if (!player.onGround)
    {
        if (player.vy < -320) return NINJA_RISE;
        if (player.vy > 320) return NINJA_FALL;
        return NINJA_FLIP0 + ((vtimer >> 2) & 3);   // somersault at the peak
    }
    if (landTimer) return NINJA_LAND;
    s16 speed = player.vx < 0 ? -player.vx : player.vx;
    if (speed < 96)
    {
        runDistance = 0;
        return NINJA_IDLE0 + ((vtimer >> 4) & 3);
    }
    runDistance += speed;   // no division in the frame loop: step the frame every 7 px
    while (runDistance >= 7 * 256)
    {
        runDistance -= 7 * 256;
        runFrame = (runFrame + 1) & 7;
    }
    return NINJA_RUN0 + runFrame;
}

typedef struct
{
    u8 count, first;
    s8 x[3], y[3];
} HeroExt;

// Rooms are several screens wide and the VDP's sprite coordinates wrap around every 512 pixels: what
// is far from the camera must be hidden, or it shows up again as a ghost on screen. (x, y) = top-left
// of a sprite of 32 x 48 at most, in screen pixels.
static u8 offScreen(s16 x, s16 y)
{
    return x < -32 || x > 320 || y < -48 || y > 224;
}
static const HeroExt HERO_EXT[NINJA_FRAME_COUNT] = NINJA_EXT_TABLE;

